class CacheFailure extends Error {
           error_kind                                     ;
  constructor(error_kind                                     , message        ) {
    super(message);
    this.name = 'CacheFailure';
    this.error_kind = error_kind;
  }
}

async function useStorage   (action                  )             {
  try {
    return await action();
  } catch (error) {
    throw new CacheFailure('storage', error instanceof Error ? error.message : String(error));
  }
}

const project_scope = new URL('../', self.registration.scope).href;
const cache_name = `emergent-content:v1:${project_scope}`;
const legacy_cache_name = `emergent-static:${self.registration.scope}`;
const max_cache_bytes = 384 * 1024 * 1024;
const max_cache_entries = 384;
const integrity_header = 'x-emergent-integrity';
const size_header = 'x-emergent-size';

function fileFormat(path        )         {
  return path.split('/').at(-1)?.split('.').at(-1)?.toLowerCase() ?? '';
}

const assets = new Map               (Object.entries(CACHE_MANIFEST.files).map(([path, integrity]) => {
  const url = new URL(path, self.registration.scope);
  const size_bytes = CACHE_MANIFEST.sizes[path];
  const format = fileFormat(path);
  // Include size and format so identical bytes requested as different media
  // cannot borrow a response with incompatible headers.
  const digest = integrity.slice('sha256-'.length).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const key = new URL(`__content__/v1/${digest}/${size_bytes}/${format}`, project_scope).href;
  return [url.pathname, { url: url.href, key, integrity, size_bytes, format }];
}));

async function withLock   (name        , signal                         , action                  )             {
  if (typeof navigator !== 'undefined' && navigator.locks) {
    return navigator.locks.request(`${cache_name}:${name}`, { signal }, action);
  }
  if (signal?.aborted) throw signal.reason;
  return action();
}

async function cachedAsset(cache       , asset       )                                {
  const response = await cache.match(asset.key);
  if (response?.headers.get(integrity_header) === asset.integrity && response.headers.get(size_header) === String(asset.size_bytes)) return response;
  return undefined;
}

                                                  

async function legacyIndex()                                      {
  const index = new Map                       ();
  const names = await caches.keys();
  for (const name of names.filter(name => name.startsWith(`emergent-static:${project_scope}`))) {
    const cache = await caches.open(name);
    for (const key of await cache.keys()) {
      const url = new URL(key.url);
      const integrity = url.searchParams.get('emergent_hash');
      if (!integrity) continue;
      const id = `${integrity}:${fileFormat(url.pathname)}`;
      const entries = index.get(id) ?? [];
      entries.push({ cache, key });
      index.set(id, entries);
    }
  }
  return index;
}

async function verifyResponse(response          , asset       , onChunk                         )                    {
  let buffer             ;
  if (response.body) {
    const counted = response.body.pipeThrough(new TransformStream({
      transform(chunk            , controller) {
        onChunk?.(chunk.byteLength);
        controller.enqueue(chunk);
      },
    }));
    buffer = await new Response(counted).arrayBuffer();
  } else {
    buffer = await response.arrayBuffer();
    onChunk?.(buffer.byteLength);
  }
  const hash = new Uint8Array(await crypto.subtle.digest('SHA-256', buffer));
  const integrity = `sha256-${btoa(String.fromCharCode(...hash))}`;
  if (integrity !== asset.integrity || buffer.byteLength !== asset.size_bytes) {
    throw new CacheFailure('integrity', `Game resource verification failed: ${asset.url}`);
  }
  const headers = new Headers(response.headers);
  headers.delete('content-encoding');
  headers.delete('content-length');
  headers.set(integrity_header, integrity);
  headers.set(size_header, String(buffer.byteLength));
  return new Response(buffer, { status: response.status, statusText: response.statusText, headers });
}

async function migrateAsset(index                            , asset       )                                {
  for (const entry of index.get(`${asset.integrity}:${asset.format}`) ?? []) {
    const response = await entry.cache.match(entry.key);
    if (!response) continue;
    try { return await verifyResponse(response, asset); }
    catch (error) {
      // Old entries may be evicted or malformed. Never promote unverified
      // bytes, and leave other scopes' legacy caches under their own workers.
      if (!(error instanceof CacheFailure) || error.error_kind !== 'integrity') throw error;
    }
  }
  return undefined;
}

async function trimCache(cache       )                {
  await withLock('trim', undefined, async () => {
    const protected_keys = new Set([...assets.values()].map(asset => asset.key));
    const entries = await Promise.all((await cache.keys()).map(async key => ({ key, size_bytes: Number((await cache.match(key))?.headers.get(size_header) ?? 0) })));
    let bytes = entries.reduce((sum, entry) => sum + (Number.isFinite(entry.size_bytes) ? entry.size_bytes : 0), 0);
    let count = entries.length;
    // Cache.keys() preserves insertion order. Bound retained historical
    // content without deleting another branch on every activation.
    for (const entry of entries) {
      if (bytes <= max_cache_bytes && count <= max_cache_entries) break;
      if (protected_keys.has(entry.key.url)) continue;
      if (await cache.delete(entry.key)) { bytes -= entry.size_bytes; count--; }
    }
  });
}

function initialProgress()                {
  return {
    type: 'cache_progress',
    cache_id: CACHE_MANIFEST.cache_id,
    phase: 'checking',
    downloaded_bytes: 0,
    total_bytes: 0,
    cached_bytes: 0,
    cached_files: 0,
    completed_files: 0,
    total_files: assets.size,
  };
}

let progress = initialProgress();
let preparation                       = null;
let preparation_controller                         = null;
let last_report_at = 0;
let reports = Promise.resolve();

function reportProgress(force = false)                {
  const now = Date.now();
  if (!force && now - last_report_at < 100) return reports;
  last_report_at = now;
  // Read the latest snapshot at delivery time so a slow clients lookup cannot
  // publish an older percentage after a direct prepare_cache reply.
  reports = reports.catch(() => undefined).then(async () => {
    const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const client of clients) {
      if (!client.url.startsWith(self.registration.scope)) continue;
      // A tab can close between the lookup and delivery; keep other tabs and
      // the cache preparation independent of that messaging failure.
      try { client.postMessage({ ...progress }); } catch { /* Closed client. */ }
    }
  }).catch(() => undefined);
  return reports;
}

async function downloadAsset(asset       , signal              , onChunk                         )                    {
  try {
    const download_url = new URL(asset.url);
    download_url.searchParams.set('v', asset.integrity);
    // Native fetch integrity buffers the entire response before exposing its
    // stream. Verify it ourselves after counting decoded chunks instead.
    const response = await fetch(download_url, { cache: 'no-store', signal });
    if (!response.ok) throw new CacheFailure('network', `Game resource download failed: ${asset.url}`);
    return await verifyResponse(response, asset, onChunk);
  } catch (error) {
    if (error instanceof CacheFailure) throw error;
    throw new CacheFailure('network', error instanceof Error ? error.message : String(error));
  }
}

async function runPreparation()                {
  progress = initialProgress();
  void reportProgress(true).catch(() => undefined);
  const controller = new AbortController();
  preparation_controller = controller;
  try {
    const unique_assets = new Map([...assets.values()].map(asset => [asset.key, asset]));
    if (unique_assets.size > max_cache_entries || [...unique_assets.values()].reduce((sum, asset) => sum + asset.size_bytes, 0) > max_cache_bytes) {
      throw new CacheFailure('storage', 'This game exceeds the persistent content cache budget');
    }
    const cache = await useStorage(() => caches.open(cache_name));
    const legacy = await useStorage(legacyIndex);
    if (controller.signal.aborted) throw controller.signal.reason;
    const checked = await Promise.all([...assets.values()].map(async asset => ({
      asset,
      cached: Boolean(await useStorage(async () => {
        if (await cachedAsset(cache, asset)) return true;
        const migrated = await migrateAsset(legacy, asset);
        if (!migrated) return false;
        await cache.put(asset.key, migrated);
        return true;
      })),
    })));
    if (controller.signal.aborted) throw controller.signal.reason;
    const pending = new Map                                         ();
    for (const { asset, cached } of checked) {
      if (cached) {
        progress.cached_bytes += asset.size_bytes;
        progress.cached_files += 1;
        progress.completed_files += 1;
      } else {
        const group = pending.get(asset.key);
        if (group) group.files++;
        else { pending.set(asset.key, { asset, files: 1 }); progress.total_bytes += asset.size_bytes; }
      }
    }
    progress.phase = pending.size ? 'downloading' : 'ready';
    await reportProgress(true);
    await Promise.all([...pending.values()].map(async ({ asset, files }) => withLock(asset.key, controller.signal, async () => {
      // Another branch may have finished this content while this worker waited.
      if (await useStorage(() => cachedAsset(cache, asset))) {
        progress.total_bytes -= asset.size_bytes;
        progress.cached_bytes += asset.size_bytes * files;
        progress.cached_files += files;
        progress.completed_files += files;
        void reportProgress(true);
        return;
      }
      const response = await downloadAsset(asset, controller.signal, bytes => {
        if (progress.phase !== 'downloading' || controller.signal.aborted) return;
        progress.downloaded_bytes += bytes;
        void reportProgress().catch(() => undefined);
      });
      if (controller.signal.aborted) throw controller.signal.reason;
      await useStorage(() => cache.put(asset.key, response));
      if (progress.phase !== 'downloading' || controller.signal.aborted) return;
      progress.completed_files += files;
      void reportProgress().catch(() => undefined);
    })));
    if (controller.signal.aborted) throw controller.signal.reason;
    progress.phase = 'ready';
    await reportProgress(true);
    // Collection failure must not turn an already verified game into an error.
    await trimCache(cache).catch(() => undefined);
  } catch (error) {
    // Cancellation wins over a late storage/read error from the same attempt.
    const failure = controller.signal.aborted ? controller.signal.reason : error;
    controller.abort(error);
    progress.phase = 'failed';
    progress.error = failure instanceof Error ? failure.message : String(failure);
    progress.error_kind = failure instanceof CacheFailure ? failure.error_kind : 'network';
    await reportProgress(true).catch(() => undefined);
    throw failure;
  }
}

function prepareCache()                {
  // Retain only an in-flight promise. A later page checks the cache again so
  // browser storage eviction is repaired without requiring a worker update.
  if (!preparation) {
    preparation = runPreparation().finally(() => {
      preparation = null;
      preparation_controller = null;
    });
  }
  return preparation;
}

self.addEventListener('install', event => {
  event.waitUntil(prepareCache().then(() => self.skipWaiting()));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    // Only the upgraded scope retires its old storage. Other scopes and shared
    // historical content remain usable during gradual worker rollout.
    await caches.delete(legacy_cache_name).catch(() => undefined);
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'prepare_cache') {
    const ready = prepareCache();
    event.source?.postMessage({ ...progress });
    event.waitUntil(ready.catch(() => undefined));
  }
  if (event.data?.type === 'cancel_cache_preparation' && preparation && preparation_controller && progress.phase !== 'ready' && progress.phase !== 'failed') {
    const error = new CacheFailure('network', 'Game resource download timed out');
    progress.phase = 'failed';
    progress.error = error.message;
    progress.error_kind = error.error_kind;
    preparation_controller.abort(error);
    event.waitUntil(reportProgress(true));
  }
  // A forced reload can produce an uncontrolled page even with an active worker.
  if (event.data?.type === 'claim_clients') event.waitUntil(self.clients.claim());
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET' || request.mode === 'navigate' || request.headers.has('range')) return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  const asset = assets.get(url.pathname);
  if (!asset) return;
  event.respondWith((async () => {
    const cache = await caches.open(cache_name).catch(() => null);
    return withLock(asset.key, undefined, async () => {
      const cached = cache ? await cachedAsset(cache, asset).catch(() => undefined) : undefined;
      if (cached) return cached;
      const response = await downloadAsset(asset);
      // Storage can become unavailable after installation; keep verified network
      // resources playable without changing the completed preparation counters.
      await cache?.put(asset.key, response.clone()).catch(() => undefined);
      if (cache) await trimCache(cache).catch(() => undefined);
      return response;
    });
  })());
});
